// Extract message and sessionId from incoming request
// Handle both JSON and FormData (multipart) requests
const inputItem = $input.first();
const body = inputItem.json.body || inputItem.json;
const message = body.message || body.text || '';
const sessionId = body.sessionId || 'default-session';

console.log('Received message:', message, 'Session:', sessionId);

// Check for binary data (file uploads)
const binaryData = inputItem.binary;
const hasFiles = binaryData && Object.keys(binaryData).length > 0;

const fileInfo = [];
if (hasFiles) {
    for (const [key, value] of Object.entries(binaryData)) {
        fileInfo.push({
            fieldName: key,
            fileName: value.fileName || 'unknown',
            mimeType: value.mimeType || 'application/octet-stream',
            fileSize: value.fileSize || 0
        });
        console.log('File uploaded:', key, value.fileName, value.mimeType);
    }
}

// Return with binary data preserved for downstream nodes
const result = {
    json: {
        message: message,
        sessionId: sessionId,
        hasFiles: hasFiles,
        fileCount: fileInfo.length,
        files: fileInfo
    }
};

// Preserve binary data for multimodal processing
if (hasFiles) {
    result.binary = binaryData;
}

return [result];

// Format multimodal input for AI Agent
// Converts binary files to base64 and prepares message with image context
const inputItem = $input.first();
const { message, sessionId, hasFiles, files } = inputItem.json;
const binaryData = inputItem.binary;

let formattedMessage = message;
const imageData = [];

if (hasFiles && binaryData) {
    // Build file context for the message
    const fileDescriptions = [];

    for (const [key, value] of Object.entries(binaryData)) {
        const mimeType = value.mimeType || 'application/octet-stream';
        const fileName = value.fileName || 'unknown';

        // For images, extract base64 data
        if (mimeType.startsWith('image/')) {
            // Get base64 data from binary
            const base64Data = value.data;
            imageData.push({
                mimeType: mimeType,
                data: base64Data,
                fileName: fileName
            });
            fileDescriptions.push(`[Image: ${fileName}]`);
        } else {
            // For non-image files, just describe them
            fileDescriptions.push(`[File: ${fileName} (${mimeType})]`);
        }
    }

    // Prepend file context to message
    if (fileDescriptions.length > 0) {
        const fileContext = 'The user has attached: ' + fileDescriptions.join(', ') + '\n\n';
        formattedMessage = fileContext + (message || 'Please analyze the attached files.');
    }
}

// Output formatted message with image data for multimodal processing
const result = {
    json: {
        message: formattedMessage,
        sessionId: sessionId,
        hasImages: imageData.length > 0,
        imageCount: imageData.length,
        images: imageData
    }
};

// Preserve binary for models that support direct binary input
if (binaryData) {
    result.binary = binaryData;
}

return [result];

// Extract response from AI Agent output
const input = $input.first().json;
let response = '';

// AI Agent outputs to 'output' field
if (input.output) {
    response = input.output;
} else if (input.text) {
    response = input.text;
}

// Build SSE formatted response
let sseResponse = 'event: workflow:start\ndata: {}\n\n';
const dataPayload = JSON.stringify({ content: response });
sseResponse += 'event: data\ndata: ' + dataPayload + '\n\n';
sseResponse += 'event: workflow:end\ndata: {}\n\n';

return [{
  json: {
    sseResponse: sseResponse
  }
}];
